import { ICONS } from './icons-data';

/*
 * lucide icons for agents (`icon()` / `icons()` in execute). Data is generated by
 * scripts/gen-icons.mjs; every icon is path data on a 24×24 grid drawn as a 2px round stroke.
 */

/** "ArrowRight", "arrow_right", "arrow right" → "arrow-right". */
export const iconKey = (name: string) =>
  name.trim().replace(/Icon$/, '').replace(/([a-z0-9])([A-Z])/g, '$1-$2').replace(/[\s_]+/g, '-').toLowerCase();

export function iconPath(name: string): string | undefined {
  return ICONS[iconKey(name)];
}

/** Names that best match a query: exact, prefix, then substring of any word. */
export function searchIcons(query: string, limit = 24): string[] {
  const q = iconKey(query);
  if (!q) return [];
  const names = Object.keys(ICONS);
  const words = q.split('-').filter(Boolean);
  const score = (n: string) => (n === q ? 0 : n.startsWith(q) ? 1 : n.includes(q) ? 2 : words.every((w) => n.includes(w)) ? 3 : words.some((w) => w.length > 2 && n.includes(w)) ? 4 : 9);
  const hits = names.map((n) => [n, score(n)] as const).filter(([, s]) => s < 9).sort((a, b) => a[1] - b[1] || a[0].length - b[0].length).slice(0, limit).map(([n]) => n);
  if (hits.length) return hits;
  // Typos ("serch"): closest names by edit distance.
  return names.map((n) => [n, distance(n, q)] as const).filter(([, d]) => d <= 2).sort((a, b) => a[1] - b[1]).slice(0, limit).map(([n]) => n);
}

function distance(a: string, b: string): number {
  if (Math.abs(a.length - b.length) > 2) return 9;
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) cur[j] = Math.min(prev[j]! + 1, cur[j - 1]! + 1, prev[j - 1]! + (a[i - 1] === b[j - 1] ? 0 : 1));
    prev = cur;
  }
  return prev[b.length]!;
}

export const ICON_COUNT = Object.keys(ICONS).length;
